using System;
using System.IO;
using System.Linq;
using CastleFight;
using Newtonsoft.Json.Linq;
using UnityEngine;
public static class HumanMatchChecks {
    static int checks;static JObject data;static JArray cases;
    static void Require(bool value,string what){checks++;if(!value)throw new Exception("Human Godot parity: "+what);}
    static void Close(float value,float expected,string what,float tolerance=.015f)=>Require(Mathf.Abs(value-expected)<tolerance,what+" ("+value+" vs "+expected+")");
    static HumanMatch Game(int gold=10000,int wood=10000){var m=new HumanMatch((JObject)data.DeepClone(),0);m.Gold[0]=gold;m.Wood[0]=wood;return m;}
    static void Ticks(HumanMatch m,int ticks){for(int i=0;i<ticks;i++)m.Step(.05f);}
    static HumanMatch.Hut Build(HumanMatch m,string raw,int x=7,int y=15){int k=m.Kind(raw);Require(m.TryBuild(0,k,x,y,out var e),"build "+raw+" "+e);var h=m.Huts.Last();m.Builders[0].position=h.position+new Vector2(0,-Mathf.Sign(h.position.y)*2.4f);for(int i=0;i<40&&!h.paid;i++)m.Step(.05f);Require(h.paid,"construction completes "+raw);return h;}
    static void Freeze(HumanMatch m){foreach(var l in m.Lines){l.speed=0;l.regen=0;}}
    static HumanMatch.Unit Unit(HumanMatch m,string building,int team,Vector2 p){var u=m.Spawn(team,m.Kind(building),p);u.onRoad=true;u.cooldown=100;return u;}
    public static void Run() {
        checks=0;cases=new JArray();data=JObject.Parse(File.ReadAllText("Assets/Resources/pc-human.json"));
        var roster=Game();Require(roster.Lines.Length==16&&roster.BaseKinds.Length==11,"16 buildings / 11 initial options");Require(roster.Lines.Count(l=>l.Producer)==11,"11 complete Human unit types");Require(roster.Abilities.Properties().Count()==47,"47 Human ability definitions and dependencies");
        Require(roster.Lines[0].building=="h000"&&roster.Lines[1].building=="h003"&&roster.Lines[2].building=="h004","existing Q/W/E identities preserved");
        foreach(var l in roster.Lines)Require(l.upgrades.All(raw=>roster.Kind(raw)>=0),"all upgrade targets resolved "+l.building);
        var economy=Game(1000,0);Require(!economy.TryBuild(2,0,0,0,out _),"invalid team");Require(!economy.TryBuild(0,-1,0,0,out _),"invalid kind");Require(!economy.TryBuild(0,0,-1,0,out _),"outside cell");
        Require(economy.TryBuild(0,0,7,15,out _),"reserve construction");Close(economy.Gold[0],1000,"queue reserves, does not spend");Close(economy.AvailableGold(0),900,"reserved funds unavailable");
        Require(!economy.TryBuild(0,0,7,15,out _),"occupied or reserved plot");Require(economy.Wood[0]==0,"no wood reward for queued construction");
        Require(economy.MoveBuilder(0,new Vector2(-150,10)),"worker move accepted");Require(economy.Huts.Count==0&&economy.AvailableGold(0)==1000,"cancel restores reservation");
        Require(!economy.MoveBuilder(0,new Vector2(float.NaN,0))&&!economy.MoveBuilder(0,new Vector2(150,10)),"invalid or enemy-base worker orders rejected");
        var h=Build(economy,"h000");Close(economy.Gold[0],900,"construction payment on completion");Require(economy.Wood[0]==100,"ordinary wood reward 100%");Close(economy.Income(0),7,"ordinary producer income 2%");Close(economy.Interval(h),20,"base production 15 + 100/20");
        h.hp=h.maxHp*.5f;Require(economy.Upgrade(0,h.id,economy.Kind("h039"),out _),"barracks guard upgrade");Close(h.spent,275,"cumulative gold includes upgrade");Close(economy.Interval(h),28.75f,"production uses cumulative investment");Close(h.spawnLeft,28.75f,"upgrade resets production timer");Close(economy.Gold[0],725,"upgrade charges incremental price 175");Require(economy.Wood[0]==275,"upgrade grants only incremental wood");Close(economy.Income(0),10.5f,"income accumulates base and upgrade");Close(h.hp/h.maxHp,.5f,"upgrade preserves health ratio");
        h.spawnLeft=.05f;Require(economy.PauseHut(0,h.id,true),"pause producer");Ticks(economy,20);Require(!economy.Units.Any(u=>u.team==0),"paused producer does not train");Close(economy.Income(0),10.5f,"pause keeps building income");economy.PauseHut(0,h.id,false);Ticks(economy,2);Require(economy.Units.Any(u=>u.kind==economy.Kind("h039")),"upgraded producer trains guard");
        float gold=economy.Gold[0];Require(economy.Sell(0,h.id),"sell own building");Close(economy.Gold[0]-gold,20,"Godot sale returns 20% original base cost");Require(economy.Huts.Count==0&&economy.Income(0)==5,"sell frees plot and removes income");
        foreach(var branch in new[]{new[]{"h003","h0A1"},new[]{"h003","h05D"},new[]{"h037","h038","h072"}}) {
            var m=Game();var hut=Build(m,branch[0]);int spent=m.Lines[m.Kind(branch[0])].cost;foreach(var next in branch.Skip(1)){Require(m.Upgrade(0,hut.id,m.Kind(next),out _),"upgrade branch "+next);spent+=m.Lines[m.Kind(next)].cost;Close(hut.spawnLeft,15+spent/20f,"branch interval "+next);}Require(hut.kind==m.Kind(branch.Last()),"correct final branch");
        }
        var chapel=Game(1000,0);var church=Build(chapel,"h037");Require(chapel.Upgrade(0,church.id,chapel.Kind("h038"),out _),"cathedral wood funding");Require(chapel.Wood[0]==525,"chapel + cathedral wood 525");Require(chapel.Upgrade(0,church.id,chapel.Kind("h072"),out _),"holy abode costs 500 wood");Require(chapel.Wood[0]==75&&chapel.LegendaryUsed(0)==1,"legendary 25% wood and slot");Close(chapel.Interval(church),51.25f,"holy abode interval from 725 invested gold");
        var legends=Game();Build(legends,"h05G");Require(legends.PurchaseError(0,legends.Kind("h05G"))!="","one legendary slot enforced");Require(!Game(1000,0).TryBuild(0,roster.Kind("h006"),7,15,out _),"wood cost blocks tower");
        var income=Game(150,300);Build(income,"h006");Ticks(income,4000-income.TickCount);Close(income.Gold[0],121,"fractional income carries across 20 payments",.1f);
        var siege=Game(210,0);var mortarHut=Build(siege,"h004");Require(siege.Wood[0]==158,"siege wood rounds 75% of 210 to 158");Close(siege.Income(0),8.57f,"siege income 1.7%");Close(siege.Interval(mortarHut),25.5f,"mortar native cadence");
        var cadence=Game();var prod=Build(cadence,"h000");prod.spawnLeft=20;Ticks(cadence,390);Require(cadence.Spawned==0,"no early production");Ticks(cadence,20);Require(cadence.Spawned==1,"full production interval releases one unit");
        var capped=Game();Freeze(capped);var cappedHut=Build(capped,"h000");for(int i=0;i<160;i++)Unit(capped,"h000",0,Vector2.zero);cappedHut.spawnLeft=.01f;Ticks(capped,220);Close(cappedHut.spawnLeft,0,"full army freezes production at zero instead of banking overdue units");int total=capped.Spawned;capped.DamageUnit(capped.Units[0],1000,1,"chaos",true,true);capped.Step(.05f);Require(capped.Spawned==total+1&&capped.Units.Count(u=>u.hp>0)==160,"one free slot releases exactly one waiting unit");Close(cappedHut.spawnLeft,20,"resumed release begins a fresh native interval",.1f);Ticks(capped,20);Require(capped.Spawned==total+1,"no rapid backlog after army limit");
        var interrupted=Game();interrupted.TryBuild(0,0,7,15,out _);var unfinished=interrupted.Huts[0];interrupted.Builders[0].position=unfinished.position+new Vector2(0,-2.4f);interrupted.Step(.05f);Require(unfinished.started&&!unfinished.paid,"builder physically starts reserved construction");float leftBuild=unfinished.buildLeft;interrupted.MoveBuilder(0,new Vector2(-150,10));Ticks(interrupted,5);Close(unfinished.buildLeft,leftBuild,"interrupted construction pauses");Require(interrupted.ResumeBuilding(0,unfinished.id),"resume unfinished building");Ticks(interrupted,250);Require(unfinished.paid,"resumed construction completes");
        for(int y=0;y<24;y++)for(int x=0;x<32;x++)if(HumanMatch.LegalCell(0,x,y)){var p=HumanMatch.Plot(0,x,y);Require(Mathf.Abs(p.y*30)>=448&&Mathf.Abs(p.y*30)<=1984,"plot outside road");Require(Mathf.Abs(Mathf.Abs(p.x*30)-3520)>=127.9f,"plot outside wall");}
        var defense=new HumanMatch((JObject)data.DeepClone(),0,1,0,1);defense.Gold[0]=10000;defense.Wood[0]=10000;
        var defended=Build(defense,"h006");Close(defended.maxHp,1700,"defense aspect adds 200 tower health");Close(defense.BuildingArmor(defended),10,"defense aspect adds two tower armor");var defendedArtillery=Build(defense,"h001",9,15);Close(defendedArtillery.cooldown,12.5f,"defense artillery fires 20 percent faster",.06f);
        var reinforce=new HumanMatch((JObject)data.DeepClone(),0,1,1,0);reinforce.Gold[0]=10000;reinforce.Wood[0]=10000;var reinforcing=Build(reinforce,"h000");reinforcing.spawnLeft=1000;Build(reinforce,"h05G",9,15);
        while(reinforce.Elapsed<30.1f)reinforce.Step(.05f);Require(reinforce.AspectExtras==1&&reinforce.ShrineExtras==0,"30 second reinforcement bypasses shrine duplication");reinforce.PauseHut(0,reinforcing.id,true);while(reinforce.Elapsed<60.2f)reinforce.Step(.05f);Require(reinforce.AspectExtras==1,"paused producer excluded from reinforcement");
        MissileChecks();SpellChecks();BuilderChecks();FoundationChecks();
        var a=new HumanMatch((JObject)data.DeepClone(),2000,2);var b=new HumanMatch((JObject)data.DeepClone(),2000,2);
        foreach(var m in new[]{a,b}){m.TryBuild(0,0,7,15,out _);m.TryBuild(0,1,9,15,out _);m.TryBuild(0,2,11,15,out _);m.TryBuild(0,4,13,15,out _);m.TryBuild(0,5,15,15,out _);m.TryBuild(0,3,17,15,out _);}
        for(int i=0;i<4000;i++){a.Step(.05f);b.Step(.05f);}Require(a.Spawned>15&&a.Kills>0&&a.SpellsCast>0,"mixed human army trains, fights and casts");Require(a.Kills==b.Kills&&a.Spawned==b.Spawned&&a.Gold.SequenceEqual(b.Gold)&&a.Wood.SequenceEqual(b.Wood),"identical commands and seed remain deterministic");Require(a.AvailableGold(0)>=0&&a.AvailableGold(1)>=0,"bots do not overspend reservations");Require(a.Units.All(u=>!float.IsNaN(u.position.x)&&!float.IsNaN(u.hp)),"combat remains finite");
        var victory=Game();victory.RescueCharges[1]=0;for(int i=0;i<20;i++){var u=victory.Spawn(0,2,new Vector2(145,i*.1f));u.onRoad=true;}for(int i=0;i<6000&&!victory.Finished;i++)victory.Step(.05f);Require(victory.Winner==0&&victory.CastleHp[1]==0,"actual castle damage produces victory");float elapsed=victory.Elapsed;victory.Step(1);Close(victory.Elapsed,elapsed,"terminal authority stops");Require(!victory.TryBuild(0,0,7,15,out _),"commands rejected after result");
        var result=new JObject {["status"]="PASS",["checks"]=checks,["productionCombatTicks"]=4000,["buildings"]=16,["baseBuildings"]=11,["unitTypes"]=11,["humanAbilityDefinitions"]=47,["source"]="Godot 0.6.17: economy, human_rules, gameplay, spell_runtime, combat_rules, round_rules",["humanMechanicsImplemented"]=true,["originalEngineFrameParity"]=false};
        Directory.CreateDirectory("../Validation/PC");File.WriteAllText("../Validation/PC/simulation-verification.json",result.ToString());Debug.Log("CF_PC_SIMULATION_PASS checks="+checks+" humans=complete-catalog spells=economy=verified");
    }
    static void MissileChecks() {
        var m=Game(0,0);Freeze(m);var gun=Unit(m,"h004",0,Vector2.zero);gun.cooldown=0;var victim=Unit(m,"h000",1,new Vector2(15,0));
        for(int i=0;i<80&&m.Shots.Count==0;i++)m.Step(.05f);Require(m.ShellsFired==1&&victim.hp==250,"mortar launches without early damage");gun.hp=0;for(int i=0;i<80&&m.ShellImpacts==0;i++)m.Step(.05f);Require(m.ShellImpacts==1&&victim.hp<250,"shell persists after shooter death and hits on arrival");
        var miss=Game(0,0);Freeze(miss);var cannon=Unit(miss,"h004",0,Vector2.zero);cannon.cooldown=0;var moving=Unit(miss,"h000",1,new Vector2(15,0));for(int i=0;i<80&&miss.Shots.Count==0;i++)miss.Step(.05f);moving.position=new Vector2(100,0);cannon.hp=0;Ticks(miss,40);Close(moving.hp,250,"artillery misses target that leaves explosion point");
        var blast=Game(0,0);Freeze(blast);foreach(float x in new[]{0f,2f,6f,9f})Unit(blast,"h000",1,new Vector2(x,0));blast.Shots.Add(new HumanMatch.Shot {id=100000,team=0,kind=2,line=2,damage=74,target=blast.Units[0].id,start=new Vector2(-15,0),end=Vector2.zero,duration=.2f});Ticks(blast,5);
        float full=250-blast.Units[0].hp,half=250-blast.Units[1].hp,quarter=250-blast.Units[2].hp;Require(full>0,"mortar splash hurts primary");Close(half/full,.5f,"half splash falloff");Close(quarter/full,.2f,"quarter splash falloff");Close(blast.Units[3].hp,250,"outside splash unaffected");
        var rifle=Game(0,0);Freeze(rifle);var shooter=Unit(rifle,"h003",0,Vector2.zero);shooter.cooldown=0;var hit=Unit(rifle,"h000",1,new Vector2(8,0));for(int i=0;i<40&&rifle.RifleShots==0;i++)rifle.Step(.05f);Require(rifle.RifleShots==1&&hit.hp<250&&rifle.Shots.Any(s=>s.kind==1),"rifle instant hit with visual tracer");shooter.cooldown=100;float hp=hit.hp;Ticks(rifle,10);Close(hit.hp,hp,"tracer expiry does not hit twice");
        var critical=Game(0,0);Freeze(critical);var marksman=Unit(critical,"h003",0,Vector2.zero);marksman.cooldown=0;marksman.critChance=1;marksman.critMultiplier=1.5f;var ordinary=Unit(critical,"h000",1,new Vector2(3,0));
        for(int i=0;i<30&&critical.RifleShots==0;i++)critical.Step(.05f);Close(250-ordinary.hp,34*1.5f*critical.Multiplier("pierce",critical.Lines[ordinary.kind].armorType)*HumanMatch.ArmorFactor(ordinary.armor),"critical damage uses native 1.5 multiplier");
        var lightning=Game(0,0);Freeze(lightning);lightning.Abilities["A01B"]["chance"]=1;var gryphon=Unit(lightning,"h015",0,Vector2.zero);gryphon.cooldown=0;for(int i=0;i<5;i++)Unit(lightning,"h000",1,new Vector2(5,i));
        for(int i=0;i<100&&lightning.Chains==0;i++)lightning.Step(.05f);Require(lightning.Chains==5&&lightning.Shots.Count(s=>s.kind==4)==5,"gryphon orb chains through five targets with visible bolts");
        var reflection=Game();Freeze(reflection);reflection.Abilities["A03G"]["deflect"]=1;var turret=Build(reflection,"h006");var shield=Unit(reflection,"h039",1,turret.position+new Vector2(10,0));
        for(int i=0;i<100&&reflection.Shots.Count==0;i++)reflection.Step(.05f);turret.cooldown=100;float turretHp=turret.hp;for(int i=0;i<100&&turret.hp==turretHp;i++)reflection.Step(.05f);Require(turret.hp<turretHp&&shield.hp==shield.maxHp,"Defend reflects a piercing missile to its source building");
        var targets=Game(0,0);var anti=Unit(targets,"h0A1",0,Vector2.zero);var ground=Unit(targets,"h000",1,Vector2.one);var air=Unit(targets,"h015",1,Vector2.one);Require(targets.WeaponFor(anti,ground)==null&&targets.WeaponFor(anti,air)!=null&&targets.WeaponFor(anti,null,true)!=null,"sniper has separate air and structure weapons");
        var tower=Game();Freeze(tower);var watch=Build(tower,"h006");var flying=Unit(tower,"h015",1,watch.position+new Vector2(10,0));float health=flying.hp;Ticks(tower,80);Require(flying.hp<health,"watch tower attacks flying targets");
        var artillery=Game();Freeze(artillery);var siege=Build(artillery,"h001");var shot=artillery.Shots.FirstOrDefault(s=>s.incendiary);Require(shot!=null&&shot.end.x>=1984f/30&&shot.end.x<=6272f/30&&Mathf.Abs(shot.end.y)<=2048f/30,"artillery aims at native enemy build region");var target=Unit(artillery,"h072",1,shot.end);target.mana=0;target.manaRegen=0;float initial=target.hp;for(int i=0;i<400&&artillery.ArtilleryFires==0;i++)artillery.Step(.05f);Require(artillery.ArtilleryFires>0&&target.hp<initial,"artillery impact creates incendiary zone: fires="+artillery.ArtilleryFires+" hp="+target.hp);float after=target.hp;Ticks(artillery,6);Require(target.hp<after,"native fire pulses apply additional damage");
    }
