        var healing=Game(0,0);Freeze(healing);var paladin=Unit(healing,"h038",0,Vector2.zero);var ally=Unit(healing,"h000",0,new Vector2(1,0));ally.hp=100;Require(healing.Cast(paladin,"A03K",ally.id),"paladin heals ally");paladin.spellTimers["A03K"]=7;Close(ally.hp,225,"heal 25 plus first permanent health grant 100");Close(ally.maxHp,350,"paladin health grant permanent");Close(paladin.mana,167,"heal mana cost 33");healing.Step(.05f);Require(ally.effects.Any(e=>e.id=="A03I"&&e.armor==9),"paladin followup inner fire grants 9 armor");
