        var priest=Game(0,0);Freeze(priest);var crusader=Unit(priest,"h037",0,Vector2.zero);var hurt=Unit(priest,"h000",0,Vector2.one);hurt.hp=100;Require(priest.Cast(crusader,"A03K",hurt.id),"crusader heal");crusader.spellTimers["A03K"]=7;priest.Step(.05f);Require(hurt.effects.Any(e=>e.id=="A03M"&&e.armor==6)&&hurt.maxHp==250,"crusader inner fire 6 armor, no permanent health");
