        var warlock=Game(0,0);Freeze(warlock);var wizard=Unit(warlock,"h00K",0,Vector2.zero);var earth=Unit(warlock,"h000",1,new Vector2(8,0));var sky=Unit(warlock,"h015",1,new Vector2(8,1));float skyHp=sky.hp;Require(warlock.Cast(wizard,"A00K",earth.id),"warlock ground blast");Close(earth.hp,100,"Godot requested warlock damage 150");Close(sky.hp,skyHp,"warlock blast excludes air");Require(!warlock.Cast(wizard,"A00K",earth.id),"warlock cannot cast during retreat cycle");warlock.Units.RemoveAll(u=>u!=wizard);warlock.Lines[wizard.kind].speed=9;warlock.Step(.3f);Require(wizard.warlockPhase==1,"warlock 0.3 second windup");var before=wizard.position;warlock.Step(5);Require(wizard.warlockPhase==2&&Vector2.Distance(before,wizard.position)<=45.01f,"warlock retreats for exactly five seconds");before=wizard.position;warlock.Step(6.6f);Require(wizard.warlockPhase==-1&&wizard.position==before,"warlock holds 6.6 seconds then returns to normal");
