        var duplicate=Game();Build(duplicate,"h05G");for(int i=0;i<100;i++)duplicate.Spawn(0,0,Vector2.zero,true);Require(duplicate.ShrineExtras>5&&duplicate.ShrineExtras<40,"17 percent shrine produces extra trained units");int extra=duplicate.ShrineExtras;duplicate.Spawn(0,duplicate.Kind("h072"),Vector2.zero,true);Require(duplicate.ShrineExtras==extra,"legendary A070 unit excluded from shrine duplication");
