        m.CastleHp[0]=HumanMatch.CastleMax-.1f;Ticks(m,20);Close(m.CastleHp[0],HumanMatch.CastleMax,"castle regeneration capped at max hp");
        m.CastleHp[0]=HumanMatch.CastleMax;Require(m.Blink(0,new Vector2(-150,30)),"builder blink");Require(m.Builders[0].position==new Vector2(-150,30),"blink moves immediately");Require(m.Blink(0,new Vector2(150,30))&&m.InsideBase(0,m.Builders[0].position),"blink enforces own-base boundary");
