    static void FoundationChecks() {
        int firstCheck=checks;
        var pause=Game();var producer=Build(pause,"h000");var tower=Build(pause,"h006",9,15);var horn=Build(pause,"h010",11,15);var chest=Build(pause,"h008",13,15);
        float income=pause.Income(0),timer=producer.spawnLeft;var enemy=Unit(pause,"h000",1,tower.position+Vector2.right*8);enemy.hp=enemy.maxHp=100000;
        var ally=Unit(pause,"h000",0,horn.position+Vector2.one);horn.mana=7;pause.PauseAll(0,true);
        Require(producer.paused&&!tower.paused&&!horn.paused&&!chest.paused,"global pause affects producers only, matching Godot tower filter");
        Ticks(pause,40);Close(producer.spawnLeft,timer,"global pause preserves exact production progress");Close(pause.Income(0),income,"global pause preserves income including support buildings");
        Require(tower.attackSerial>0&&pause.HolyCasts>0&&ally.effects.Any(e=>e.id=="A016"),"towers and holy horn remain active during global production pause");
        pause.PauseHut(0,tower.id,true);pause.PauseAll(0,false);Require(!producer.paused&&tower.paused,"global resume leaves an individually paused tower alone");pause.PauseHut(0,tower.id,false);Require(!tower.paused,"manual tower resume remains available");
        foreach(bool started in new[]{false,true}) {
            var cancel=Game(1000,2000);cancel.MoveBuilder(0,new Vector2(-130,25));Require(cancel.TryBuild(0,cancel.Kind("h05G"),7,15,out _),"reserve cancellable legendary building");var h=cancel.Huts[0];
            if(started){cancel.Builders[0].position=h.position+new Vector2(0,-2.4f);cancel.Step(.05f);Require(h.started&&!h.paid,"cancellation fixture has physically started construction");}
            Require(cancel.ReservedGold(0)==550&&cancel.ReservedWood(0)==1500&&cancel.ReservedLegendary(0)==1,"queued construction exposes all three resource reservations");
            var stopped=cancel.Builders[0].position;Require(cancel.Sell(0,h.id),"cancel queued or partially completed construction");
            Require(cancel.AvailableGold(0)==1000&&cancel.AvailableWood(0)==2000&&cancel.LegendaryUsed(0)==0,"cancellation releases all reservations without a paid-building refund");
            Ticks(cancel,10);Require(cancel.Builders[0].position==stopped&&cancel.Builders[0].jobs.Count==0,"cancelled final build does not resurrect an old move order");
            Require(cancel.TryBuild(0,cancel.Kind("h05G"),7,15,out _),"cancelled construction frees its exact plot");
        }
        var queued=Game(1000,0);queued.TryBuild(0,0,7,15,out _);var removed=queued.Huts[0];queued.TryBuild(0,0,9,15,out _);var remaining=queued.Huts[1];queued.Sell(0,removed.id);Ticks(queued,500);Require(remaining.paid&&queued.Huts.Count==1&&queued.Builders[0].jobs.Count==0,"cancelling current build preserves and completes the next queued order");
        var moving=Game();var sold=Build(moving,"h000");var goal=new Vector2(-130,25);moving.MoveBuilder(0,goal);moving.Sell(0,sold.id);Require(moving.Builders[0].goal==goal,"selling a finished building preserves an unrelated movement order");
        var clock=Game(0,0);Close(clock.IncomeIn,10,"income countdown starts at ten seconds");Ticks(clock,65);Close(clock.IncomeIn,6.75f,"income countdown follows authority time");Ticks(clock,135);Close(clock.Gold[0],5,"income tick pays at ten seconds");Close(clock.IncomeIn,10,"income countdown resets with payment");
        foreach(int team in new[]{0,1})foreach(int col in new[]{6,7,8,9})foreach(int row in new[]{0,11,12,23}) {
            var route=new HumanMatch((JObject)data.DeepClone(),0);int x=team==0?col:31-col;var u=route.Spawn(team,0,HumanMatch.Plot(team,x,row));float closest=float.MaxValue;bool crossed=false;
            for(int i=0;i<1100;i++){route.Step(.05f);closest=Mathf.Min(closest,Vector2.Distance(u.position,HumanMatch.CastlePosition(team)));if((team==0?u.position.x:-u.position.x)>=-2016f/30){Require(Mathf.Abs(u.position.y)<2.21f,"ground unit crosses its own arch on the road");crossed=true;break;}}
            Require(crossed&&closest>route.CastleCollision,"ground route avoids own keep from both sides and both teams "+team+"/"+x+"/"+row);
        }
        var report=new JObject{["status"]="PASS",["checks"]=checks-firstCheck,["groundRoutesVerified"]=32,["source"]="Godot gameplay.set_all_production_paused, gameplay.route_through_arch, economy, game_unit.cancel_orders; interrupted construction retained per Unity workspace contract"};
        Directory.CreateDirectory("../Validation/PC");File.WriteAllText("../Validation/PC/foundation-simulation-verification.json",report.ToString());Debug.Log("CF_FOUNDATION_SIMULATION_PASS checks="+(checks-firstCheck)+" routes=32");
    }
}
